import{_ as e,o as n,c as a,X as i}from"./chunks/framework.CNGPadWr.js";const u=JSON.parse('{"title":"Process settings: runtime","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-runtime.md","filePath":"reference-runtime.md"}'),r={name:"rust/api/reference-runtime.md"};function o(d,t,s,c,l,h){return n(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="process-settings-runtime" tabindex="-1">Process settings: runtime <a class="header-anchor" href="#process-settings-runtime" aria-label="Permalink to &quot;Process settings: runtime&quot;">​</a></h1><p><code>cellpack::runtime</code> binds CPU kernels once per process and reports physical-core capacity. It does not allocate a worker pool, reserve CPUs, or change machine affinity on the application&#39;s behalf.</p><h2 id="binding-and-querying" tabindex="-1">Binding and querying <a class="header-anchor" href="#binding-and-querying" aria-label="Permalink to &quot;Binding and querying&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Input</th><th>Output / behavior</th></tr></thead><tbody><tr><td><code>KernelCap::parse</code></td><td><code>scalar, avx2,</code> or <code>avx512</code> name</td><td>Checked cap</td></tr><tr><td><code>RuntimeOptions::from_env</code></td><td>Process environment</td><td>Parsed options or an error</td></tr><tr><td><code>init</code></td><td>Explicit options</td><td>Process-lifetime <code>&amp;&#39;static Runtime</code></td></tr><tr><td><code>get</code></td><td>None</td><td>Existing runtime, or first binding from environment</td></tr><tr><td><code>Runtime::options</code></td><td>Runtime</td><td>Requested options</td></tr><tr><td><code>Runtime::isa</code></td><td>Runtime</td><td>Actual selected supported instruction set</td></tr><tr><td><code>physical_cores</code></td><td>Optional logical CPU-id slice</td><td>Physical-core count, at least one</td></tr><tr><td><code>KERNELS_ENV</code></td><td>None</td><td>Name <code>CELLPACK_KERNELS</code></td></tr></tbody></table><p><code>KernelCap::Auto</code> chooses the best supported set; <code>At(isa)</code> imposes a maximum. A cap does not require unsupported instructions. <code>init</code> with matching options returns the existing binding. Different options return <code>cellpack::Error::InvalidOptions</code> and leave the first binding intact. A previously implicit <code>get</code> can therefore prevent later incompatible explicit initialization. Initialize before constructing codec tables when explicit control is required.</p><p><code>CELLPACK_KERNELS</code> is read on first environment-based binding. Changing the environment afterward does not rebind existing contexts. Invalid or non-Unicode values fail parsing.</p><h2 id="core-topology" tabindex="-1">Core topology <a class="header-anchor" href="#core-topology" aria-label="Permalink to &quot;Core topology&quot;">​</a></h2><p><code>physical_cores(cpus)</code> deduplicates SMT siblings using package/core ids from Linux sysfs. With an empty slice it uses the caller&#39;s allowed affinity set. Where topology cannot be read, logical CPU ids are used as the fallback identity.</p><p>The query is not cached. It reports capacity rather than pinning threads. <code>LoaderConfig.cpus</code> is the separate worker-affinity declaration.</p><h2 id="complete-interface-index" tabindex="-1">Complete interface index <a class="header-anchor" href="#complete-interface-index" aria-label="Permalink to &quot;Complete interface index&quot;">​</a></h2><h3 id="structs" tabindex="-1">Structs <a class="header-anchor" href="#structs" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-runtime-struct-Runtime.html"><code>Runtime</code></a></td><td>The bound process settings.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-runtime-struct-RuntimeOptions.html"><code>RuntimeOptions</code></a></td><td>Settings the process binds once.</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-runtime-enum-KernelCap.html"><code>KernelCap</code></a></td><td>The most capable kernel set a process may use.</td></tr></tbody></table><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-runtime-constant-KERNELS_ENV.html"><code>KERNELS_ENV</code></a></td><td>Name of the kernel-cap environment variable.</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-runtime-fn-get.html"><code>get</code></a></td><td>The bound settings, binding them from the environment on first use.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-runtime-fn-init.html"><code>init</code></a></td><td>Binds the process settings. Calling it again with the same options returns the existing binding; different options are an error, as is any call after another entry point bound the settings from the environment with different options.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-runtime-fn-physical_cores.html"><code>physical_cores</code></a></td><td>Physical cores among cpus (logical CPU ids), or among the calling thread’s affinity set when cpus is empty: SMT siblings count once.</td></tr></tbody></table>',18)])])}const m=e(r,[["render",o]]);export{u as __pageData,m as default};
